#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<int> ds; // base-4 digits, most significant first
    while (n) { ds.push_back(n % 4); n /= 4; }
    reverse(ds.begin(), ds.end());
    int len = ds.size();
    if (len == 0) { cout << 0 << "\n"; return 0; }
    long long ans = 0;
    for (int k = 1; k < len; k++) ans += 1LL << (k - 1); // all shorter fancy numbers
    if (ds[0] > 1) { cout << ans + (1LL << (len - 1)) << "\n"; return 0; }
    // leading digit is 1: count same-length fancy numbers below n digit by digit
    for (int i = 1; i < len; i++) {
        int smaller = (0 < ds[i]) + (1 < ds[i]);
        ans += smaller * (1LL << (len - i - 1));
        if (ds[i] > 1) break;
    }
    cout << ans << "\n";
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        ArrayList<Integer> ds = new ArrayList<>(); // base-4 digits, most significant first
        while (n > 0) { ds.add((int) (n % 4)); n /= 4; }
        Collections.reverse(ds);
        int len = ds.size();
        if (len == 0) { System.out.println(0); return; }
        long ans = 0;
        for (int k = 1; k < len; k++) ans += 1L << (k - 1); // all shorter fancy numbers
        if (ds.get(0) > 1) { System.out.println(ans + (1L << (len - 1))); return; }
        // leading digit is 1: count same-length fancy numbers below n digit by digit
        for (int i = 1; i < len; i++) {
            int d = ds.get(i), smaller = (d > 0 ? 1 : 0) + (d > 1 ? 1 : 0);
            ans += smaller * (1L << (len - i - 1));
            if (d > 1) break;
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"slices"
)

func main() {
	var n int64
	fmt.Scan(&n)
	var ds []int // base-4 digits, most significant first
	for n > 0 {
		ds = append(ds, int(n%4))
		n /= 4
	}
	slices.Reverse(ds)
	length := len(ds)
	if length == 0 {
		fmt.Println(0)
		return
	}
	var ans int64
	for k := 1; k < length; k++ {
		ans += 1 << (k - 1) // all shorter fancy numbers
	}
	if ds[0] > 1 {
		fmt.Println(ans + 1<<(length-1))
		return
	}
	// leading digit is 1: count same-length fancy numbers below n digit by digit
	for i := 1; i < length; i++ {
		smaller := 0
		if ds[i] > 0 {
			smaller++
		}
		if ds[i] > 1 {
			smaller++
		}
		ans += int64(smaller) << (length - i - 1)
		if ds[i] > 1 {
			break
		}
	}
	fmt.Println(ans)
}
